export const ISOLATED_PROXY_ENDPOINT = "ws://127.0.0.1:19090/";
export function createBrowserConnection(connect) {
    let current;
    return {
        get(endpoint) {
            if (current !== undefined) {
                if (current.endpoint !== endpoint || current.resolved?.isConnected() === false) {
                    return Promise.reject(new Error("Browser proxy changed"));
                }
                return current.browser;
            }
            const entry = {
                endpoint,
                browser: connect(endpoint),
            };
            current = entry;
            entry.browser.then((browser) => {
                entry.resolved = browser;
            }, () => {
                if (current === entry)
                    current = undefined;
            });
            return entry.browser;
        },
        forgetIfDisconnected() {
            if (current?.resolved?.isConnected() === false)
                current = undefined;
        },
    };
}
